<script setup lang="ts">import type{Article,Question}from'@career-launch/shared';import{computed,onMounted,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{repository}from'../../services/repository';import QuestionCard from'./QuestionCard.vue';const route=useRoute();const router=useRouter();const type=computed(()=>route.query.type==='question'?'question':'article');const keyword=ref(String(route.query.keyword??''));const articles=ref<Article[]>([]);const questions=ref<Question[]>([]);const loading=ref(false);async function load(){loading.value=true;const filter=keyword.value.trim()?{keyword:keyword.value.trim()}:{};if(type.value==='article')articles.value=(await repository.knowledge.listArticles({...filter,page:1,pageSize:20})).items;else questions.value=(await repository.knowledge.listQuestions({...filter,page:1,pageSize:24})).items;loading.value=false}function setType(next:'article'|'question'){router.replace({query:{...route.query,type:next}})}function search(){router.replace({query:{...route.query,...keyword.value?{keyword:keyword.value}:{}}});load()}watch(type,load);onMounted(load)</script>
<template><section class="cl-page cl-container"><header class="knowledge-head"><div><p>启程面试宝典</p><h1>准备得更具体，表达得更从容</h1></div><form @submit.prevent="search"><input v-model="keyword" aria-label="搜索面试内容" placeholder="搜索岗位、公司或问题"/><button class="cl-primary-button">搜索</button></form></header><div class="tabs" role="tablist" aria-label="内容类型"><button role="tab" :aria-selected="type==='article'" @click="setType('article')">求职攻略</button><button role="tab" :aria-selected="type==='question'" @click="setType('question')">面试题库</button></div><p v-if="loading">正在整理内容…</p><div v-else-if="type==='article'" class="article-grid"><RouterLink v-for="article in articles" :key="article.id" class="article cl-card" :to="`/knowledge/articles/${article.id}`"><div><span>{{article.category}}</span><small>{{article.readingMinutes}} 分钟阅读</small></div><h2>{{article.title}}</h2><p>{{article.summary}}</p><footer><span v-for="tag in article.tags" :key="tag">#{{tag}}</span></footer></RouterLink></div><div v-else class="question-grid"><QuestionCard v-for="question in questions" :key="question.id" :question="question"/></div></section></template>
<style scoped>.knowledge-head{display:flex;align-items:end;justify-content:space-between;gap:24px}.knowledge-head>div>p{margin-bottom:4px;color:var(--cl-primary);font-weight:700}.knowledge-head h1{margin:0;color:var(--cl-text-strong);font-size:38px;letter-spacing:-.04em}.knowledge-head form{display:flex;gap:8px}.knowledge-head input{height:42px;min-width:280px;padding:0 13px;border:1px solid var(--cl-border);border-radius:8px;background:var(--cl-surface)}.tabs{display:flex;gap:25px;margin:34px 0 22px;border-bottom:1px solid var(--cl-border)}.tabs button{padding:0 2px 12px;border:0;border-bottom:2px solid transparent;color:var(--cl-muted);background:none;font-weight:700}.tabs button[aria-selected=true]{color:var(--cl-primary);border-color:var(--cl-primary)}.article-grid,.question-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.article{padding:22px}.article>div{display:flex;justify-content:space-between;color:var(--cl-primary);font-size:12px;font-weight:700}.article small{color:var(--cl-muted);font-weight:400}.article h2{margin:20px 0 8px;color:var(--cl-text-strong);font-size:19px}.article p{color:var(--cl-muted)}.article footer{display:flex;gap:9px;color:var(--cl-subtle);font-size:12px}@media(max-width:850px){.knowledge-head{align-items:start;flex-direction:column}.article-grid,.question-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:570px){.knowledge-head form{width:100%;flex-direction:column}.knowledge-head input{min-width:0}.article-grid,.question-grid{grid-template-columns:1fr}}</style>
